insert into impuestos_periodos(impuesto,periodo,importe,vencimiento,obs)
select d.impuesto,d.periodo,d.importe,d.vencimiento,d.obs from d
where exists (select 1 from impuestos i where i.id=d.impuesto)
on conflict (impuesto,periodo) do nothing;

select count(*) as periodos_en_la_base from impuestos_periodos;
